function drawProfiles(){document.querySelectorAll('.player-frame').forEach(e=>e.remove());const positions=['top-left','top-right','bottom-right','bottom-left'];state.teams.forEach((t,i)=>{const frame=document.createElement('button');frame.type='button';frame.className='player-frame '+positions[i];frame.style.setProperty('--team-color',colors[i]);frame.id='player-frame-'+i;frame.setAttribute('aria-label',t.name+' supporters');frame.onclick=()=>showSupporters(i);const face=document.createElement('div');face.className='profile-face';makeAvatar(face,t.supporter);if(t.supporter){const crown=document.createElement('span');crown.className='leader-crown';crown.textContent='♛';face.append(crown)}const country=document.createElement('div');country.className='player-country';country.textContent=t.name;if(rosterMode==='countries')country.prepend(countryFlag(t.flag,t.name));if(rosterMode==='teams'&&t.teamAvatar){const badge=document.createElement('img');badge.src=t.teamAvatar;badge.alt=t.name;badge.className='team-badge';country.prepend(badge)}const name=document.createElement('div');name.className='player-name';name.textContent=t.active===false?'ELIMINATED':t.supporter?.name||'YOUR PROFILE HERE';const gift=document.createElement('div');gift.className='player-gift';const icon=document.createElement('span');icon.className='gift-symbol';icon.textContent=giftLabel(i).symbol;if(['5655','5269','6064','5827'].includes(giftMap[i])){const image=document.createElement('img');image.src='/gifts/'+giftMap[i]+'.png';image.alt=giftLabel(i).name;image.addEventListener('error',()=>image.remove(),{once:true});icon.textContent='';icon.append(image)}const label=document.createElement('span');label.textContent=giftLabel(i).name+' · '+t.g;gift.append(icon,label);const comment=document.createElement('span');comment.className='play-code';comment.textContent=inputMode==='gifts'?'1 COIN GIFT':'COMMENT '+(i+1);frame.append(comment);const total=document.createElement('span');total.className='supporter-total';if(t.g>0)total.textContent=(t.supporters?.length||1)+' SUPPORTERS · TOP '+(t.supporter?.gifts||0);else{total.textContent=(inputMode==='gifts'?'NO GIFTS · '+(t.noGiftTurns||0)+'/2 TURNS':'FREE TO PLAY');if(t.noGiftTurns)total.classList.add('elimination-warning')}frame.append(face,country,name,total,gift);document.querySelector('.board-wrap').append(frame)});
const mapping=$('giftMappings');if(!mapping.contains(document.activeElement)){mapping.replaceChildren();state.teams.forEach((t,i)=>{const row=document.createElement('label');row.className='map-row';const label=document.createElement('span');label.className='map-label';label.textContent=t.flag+' '+t.name+' · '+giftLabel(i).symbol+' '+giftLabel(i).name;const input=document.createElement('select');input.id='giftId'+i;input.setAttribute('aria-label',t.name+' one coin gift');oneCoinGifts.forEach(g=>{const option=document.createElement('option');option.value=g.id;option.textContent=g.symbol+' '+g.name+' · 1 coin';option.disabled=giftMap.some((id,j)=>j!==i&&id===g.id);input.append(option)});input.value=giftMap[i]||'';input.onchange=()=>{const value=input.value.trim();if(!oneCoinGifts.some(g=>g.id===value)||giftMap.some((v,j)=>j!==i&&v===value)){message('Every country needs a unique numeric gift ID.');input.value=giftMap[i]||'';return}giftMap[i]=value;const p=oneCoinGifts.find(p=>p.id===value);if(p)state.teams[i].gift=p.symbol+' '+p.name;queueSync()};row.append(label,input);mapping.append(row)})}
$('queueAdmin').replaceChildren();state.queue.forEach(t=>{const row=document.createElement('div');row.className='queue-admin map-row';const label=document.createElement('span');label.className='request-label';label.textContent=t.requestId+' · '+t.flag+' '+t.name+' ('+(t.requests||0)+')';const minus=document.createElement('button'),plus=document.createElement('button');minus.textContent='−';plus.textContent='+';minus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:-1});plus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:1});row.append(label,minus,plus);$('queueAdmin').append(row)})}
function renderSupporters(i){const t=state.teams[i];$('supporterTitle').textContent=t.name;if(rosterMode==='countries')$('supporterTitle').prepend(countryFlag(t.flag,t.name));$('supporterList').replaceChildren();const list=[...(t.supporters||[])].sort((a,b)=>b.gifts-a.gifts||a.at-b.at);if(!list.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='No gifts yet. Be the first to support '+t.name+'.';$('supporterList').append(empty)}list.forEach((donor,rank)=>{const row=document.createElement('div');row.className='supporter-row';const pos=document.createElement('span');pos.className='supporter-rank';pos.textContent=rank===0?'♛':String(rank+1);const avatar=document.createElement('div');avatar.className='supporter-avatar';makeAvatar(avatar,donor);const info=document.createElement('div');const name=document.createElement('strong');name.textContent=donor.name;const tag=document.createElement('small');tag.textContent=rank===0?'TOP SUPPORTER':'COUNTRY SUPPORTER';info.append(name,tag);const score=document.createElement('span');score.className='supporter-score';score.textContent=String(donor.gifts);const unit=document.createElement('small');unit.textContent=donor.gifts===1?'gift':'gifts';score.append(unit);row.append(pos,avatar,info,score);$('supporterList').append(row)})}
