function remote(m){applyingRemote=true;renderLikers(m.snapshot.likers||[]);renderConnection(m);isDemoRunning=!!m.demoRunning;$('demoBanner').hidden=!isDemoRunning;$('startDemo').hidden=isDemoRunning;$('stopDemo').hidden=!isDemoRunning;serverRevision=m.revision;const s=m.snapshot;rosterMode=s.rosterMode||'countries';inputMode=s.inputMode||'comments';state=s.state;config=s.config;giftMap=s.giftMap;likeCount=s.likes||0;fans=s.fans||[];render();$('likes').textContent=new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(likeCount);const d=s.display||{};$('effects').checked=d.effects!==false;$('sound').checked=!!d.sound;$('volume').value=d.volume??20;document.body.classList.toggle('portrait',d.portrait!==false);updateModeLabels();updateVisiblePlayMode();renderRosterEditor();if(d.bg){document.body.style.setProperty('--backdrop',d.bg);localStorage.setItem('ludo-bg',d.bg)}document.querySelector('main').style.maxWidth=(Number(d.width||100)*14.4)+'px';$('liveStatus').textContent=m.status;$('liveUsername').placeholder=m.username?'@'+m.username:'نام حساب تیک‌تاک بدون @';ready=true;lastSynced=JSON.stringify(collect());applyingRemote=false}
function command(type,rest={}){if(socket?.readyState===1)socket.send(JSON.stringify({type,...rest}));else message('Connection lost. Reconnecting…')}
function authenticate(){if(streamOutput)return;const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));if(key)command('auth',{token:key})}
function openSocket(){clearTimeout(retryTimer);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=authenticate;socket.onmessage=event=>{try{const m=JSON.parse(event.data);if(m.type==='snapshot')remote(m);else if(m.type==='auth'){admin=m.ok;document.body.classList.toggle('can-manage',admin);$('authBox').hidden=admin;$('adminTools').hidden=!admin;if(admin){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));sessionStorage.setItem('ludo-admin',key);$('adminKey').value='';message('Management panel ready. Gifts and countries are preconfigured.')}else message('Invalid management key.')}else if(m.type==='effect'){effect(m.symbol);if(Number.isInteger(m.corner))$('player-frame-'+m.corner)?.classList.add('new-gift')}else if(m.type==='like-reaction')edgeHearts(m.count);else if(m.type==='last-gift')$('lastLiveGift').textContent='آخرین گیفت: '+m.giftName+' · ID '+m.giftId;else if(m.type==='notice'||m.type==='error')message(m.message)}catch(error){console.warn('Live update failed:',error.message)}};socket.onclose=()=>{admin=false;document.body.classList.remove('can-manage');$('liveStatus').textContent='ارتباط سرور قطع شد؛ تلاش مجدد…';retryTimer=setTimeout(openSocket,3000)}}
$('unlock').onclick=authenticate;$('hidePanel').onclick=()=>{document.body.classList.add('broadcast');window.scrollTo?.({top:0,behavior:'smooth'})};$('connectLive').onclick=()=>command('connect',{username:$('liveUsername').value.trim()});$('disconnectLive').onclick=()=>command('disconnect');for(let i=0;i<4;i++)$('demo'+i).onclick=()=>command('demo-gift',{corner:i});$('sendDemoComment').onclick=()=>command('demo-comment',{content:$('demoComment').value.trim(),userId:$('demoViewer').value.trim()||'viewer-1'});document.addEventListener('change',queueSync);document.addEventListener('click',()=>{if(admin)setTimeout(queueSync,0)});drawProfiles();openSocket();if(location.pathname==='/screen')document.body.classList.add('broadcast');

