const rosterTools=document.createElement('details');rosterTools.id='rosterTools';rosterTools.innerHTML=`<summary>کشورها، تیم‌ها و عکس شرکت‌کننده‌ها</summary><div class="map-row"><label>حالت صفحه <select id="rosterMode"><option value="countries">کشورها · Countries</option><option value="teams">تیم / افراد · Teams</option></select></label><label>روش حرکت <select id="inputMode"><option value="comments">کامنت رایگان · Free comments</option><option value="gifts">گیفت یک‌کوینی · Gifts</option><option value="both">کامنت و گیفت · Both</option></select></label></div><p>کامنت‌های 1 تا 4 مهره‌های داخل میدان را حرکت می‌دهند. درخواست ورود تیم‌های منتظر با شماره‌های 5 تا 14 است. در حالت کامنت، هیچ پرداختی لازم نیست و قانون حذف بدون گیفت غیرفعال است.</p><div class="map-row"><select id="rosterEntry" aria-label="انتخاب تیم"></select><input id="rosterName" placeholder="English team or person name" maxlength="32" aria-label="Team name"><input id="rosterFlag" placeholder="🇦🇫" aria-label="Flag" maxlength="12"></div><div class="map-row"><label>عکس فرد / تیم <input id="rosterPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="saveRoster">ذخیره نام و عکس</button><button id="clearRosterPhoto">حذف عکس</button></div><img id="rosterPreview" class="roster-preview" alt="Team picture preview" hidden><p>نام نمایشی را انگلیسی وارد کنید. عکس تیم جای بیرق می‌آید؛ عکس بزرگ داخل فریم همچنان حامی برتر است. گیفت هر گوشه حداکثر ۱ کوین و مستقل از کشور یا تیم جایگزین است.</p>`;
$('adminTools').prepend(rosterTools);let draftPhoto=undefined;
function selectedEntry(){const [kind,key]=$('rosterEntry').value.split(':');return kind==='active'?state.teams[Number(key)]:state.queue.find(t=>t.requestId===Number(key))}
function fillRosterDraft(){const t=selectedEntry();if(!t)return;draftPhoto=undefined;$('rosterName').value=t.name;$('rosterFlag').value=t.flag||'';$('rosterPhoto').value='';$('rosterPreview').hidden=!t.teamAvatar;if(t.teamAvatar)$('rosterPreview').src=t.teamAvatar}
function renderRosterEditor(){if(!$('rosterEntry'))return;const select=$('rosterEntry'),prior=select.value;if(rosterTools.contains(document.activeElement))return;select.replaceChildren();state.teams.forEach((t,i)=>{const o=document.createElement('option');o.value='active:'+i;o.textContent='IN GAME '+(i+1)+' · '+t.name;select.append(o)});state.queue.forEach(t=>{const o=document.createElement('option');o.value='queue:'+t.requestId;o.textContent='WAITING '+t.requestId+' · '+t.name;select.append(o)});if([...select.options].some(o=>o.value===prior))select.value=prior;if(!prior||!selectedEntry())fillRosterDraft();$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
$('rosterEntry').onchange=fillRosterDraft;$('rosterMode').onchange=()=>{rosterMode=$('rosterMode').value;render();updateModeLabels();queueSync()};$('inputMode').onchange=()=>command('set-input-mode',{inputMode:$('inputMode').value});
$('rosterPhoto').onchange=async()=>{const file=$('rosterPhoto').files[0];if(!file)return;if(file.size>5*1024*1024){message('Choose an image smaller than 5 MB.');return}try{const img=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const ctx=canvas.getContext('2d');const side=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,160,160);draftPhoto=canvas.toDataURL('image/webp',.75);img.close();if(draftPhoto.length>40000){message('Image is too large. Choose a simpler image.');draftPhoto=undefined;return}$('rosterPreview').src=draftPhoto;$('rosterPreview').hidden=false}catch{message('This image could not be opened. Use JPG, PNG or WebP.')}};
$('clearRosterPhoto').onclick=()=>{draftPhoto='';$('rosterPreview').hidden=true};$('saveRoster').onclick=()=>{const t=selectedEntry(),name=$('rosterName').value.trim();if(!t)return;if(!name||/[^\x20-\x7E]/.test(name)){message('Enter an English display name.');return}t.name=name;t.flag=$('rosterFlag').value.trim()||'🏳';if(draftPhoto!==undefined)t.teamAvatar=draftPhoto;config=state.teams.map(t=>[t.flag,t.name,t.gift].join('|')).concat(state.queue.slice().sort((a,b)=>a.requestId-b.requestId).map(t=>[t.flag,t.name].join('|'))).join('\n');draftPhoto=undefined;render();queueSync();message('Team name and picture saved.');fillRosterDraft()};
function updateModeLabels(){const team=rosterMode==='teams';const heading=document.querySelector('.live-heading h1');heading.textContent=team?'Back your team.':'Raise your flag.';document.querySelector('.live-heading .eyebrow').textContent=team?'FOUR TEAMS. ONE ARENA.':'FOUR COUNTRIES. ONE ARENA.';document.querySelector('.live-heading p').textContent=inputMode==='gifts'?'Send a 1-coin gift. Support your favorite.':'Play for free. Comment 1, 2, 3 or 4 to move.';const arenaHeader=document.querySelector('.arena-head');arenaHeader.children[0].textContent=(team?'TEAM':'COUNTRY')+' BATTLE';arenaHeader.children[1].textContent=inputMode==='gifts'?'NO GIFTS · OUT AFTER 2 TURNS':'FREE PLAY · COMMENT 1–4';document.querySelector('.queue-hint').textContent='Comment a waiting '+(team?'team':'country')+'’s number (5–14). Most requested enters next.';document.querySelector('.arena-caption').children[0].textContent='♛ TOP GIFTER IN EVERY FRAME';$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
let lastMotionId=null;
function animateMove(){const m=state.motion;if(!m||m.phase!=='move'||m.pawn<0||m.id===lastMotionId)return;lastMotionId=m.id;if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const el=document.querySelector(`.pawn[data-team="${m.team}"][data-pawn="${m.pawn}"]`);if(!el?.animate)return;const cellAt=p=>p<52?route[(p+m.team*13)%52]:p<58?lanes[m.team][p-52]:[7,7];const end=cellAt(m.to),points=[];const cellSize=$('board').getBoundingClientRect().width/15;if(m.from<0){const home=[[2.5,2.5],[2.5,11.5],[11.5,11.5],[11.5,2.5]][m.team];points.push({transform:`translate(${(home[1]-end[1])*cellSize}px,${(home[0]-end[0])*cellSize}px) scale(1.15)`})}for(let p=Math.max(0,m.from);p<=m.to;p++){const c=cellAt(p);points.push({transform:`translate(${(c[1]-end[1])*cellSize}px,${(c[0]-end[0])*cellSize}px) scale(1.12)`})}points.push({transform:'translate(0,-3px) scale(1)'});el.animate(points,{duration:850,easing:'linear'});el.style.zIndex='12'}
renderRosterEditor();updateModeLabels();

const demoBanner=document.createElement('div');demoBanner.id='demoBanner';demoBanner.className='demo-banner';demoBanner.hidden=true;demoBanner.innerHTML='<span>DEMO · NO REAL GIFTS · FREE PREVIEW</span><button id="stopDemoBanner">Stop demo</button>';document.querySelector('.site-header').after(demoBanner);$('startDemo').onclick=()=>{command('demo-start');document.body.classList.add('broadcast');window.scrollTo?.({top:0,behavior:'smooth'})};$('stopDemo').onclick=()=>command('demo-stop');$('stopDemoBanner').onclick=()=>{command('demo-stop');document.body.classList.remove('broadcast')};

function fitMobileLive(){const main=document.querySelector('main');main.style.transform='';main.style.marginBottom='';if(!document.body.classList.contains('broadcast'))return;const demo=streamOutput||$('demoBanner').hidden?0:$('demoBanner').getBoundingClientRect().height+10;const gap=streamOutput?0:12;const available=Math.max(180,(window.visualViewport?.height||window.innerHeight)-demo-gap);const scale=Math.max(.1,Math.min((window.innerWidth-gap)/1080,available/1920));main.style.transform='scale('+scale+')';main.style.marginBottom='-'+Math.round(1920*(1-scale))+'px'}
const mobileView=window.matchMedia?.('(max-width: 780px)');if(mobileView?.matches){document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}
window.addEventListener('resize',fitMobileLive);window.visualViewport?.addEventListener('resize',fitMobileLive);new MutationObserver(()=>{if(streamOutput&&!document.body.classList.contains('broadcast'))document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}).observe(document.body,{attributes:true,attributeFilter:['class']});
const priorRemote=remote;remote=function(m){priorRemote(m);requestAnimationFrame(fitMobileLive)};

const diagnosticsBox=document.createElement('div');diagnosticsBox.id='connectionDetails';diagnosticsBox.className='connection-details';$('liveStatus').after(diagnosticsBox);$('liveUsername').placeholder='Any TikTok username · no login required';
function renderConnection(m){const box=$('connectionDetails');if(!box)return;box.replaceChildren();const c=m.connection||{};const line=document.createElement('p');line.textContent='حساب: '+(m.username?'@'+m.username:'انتخاب نشده')+' · وضعیت: '+(c.status||'disconnected')+' · تلاش: '+(c.retryAttempt||0);box.append(line);const method=document.createElement('p');method.textContent='فقط یوزرنیم هر حساب در حال لایو؛ بدون ورود، رمز، کوکی یا کلید API تیک‌تاک.';box.append(method);if(c.diagnostics?.length){const d=document.createElement('p');d.className='connection-error';d.textContent=c.diagnostics.map(d=>d.reason+(d.httpStatus?' HTTP '+d.httpStatus:'')+(d.route?' / '+d.route:'')).join(' · ');box.append(d)}if(c.retryAt){const wait=document.createElement('p');wait.textContent='تلاش بعدی: '+Math.max(0,Math.ceil((c.retryAt-Date.now())/1000))+' ثانیه دیگر';box.append(wait)}const traffic=document.createElement('p');traffic.textContent='دریافت واقعی — کامنت: '+(m.traffic?.comments||0)+' · لایک: '+(m.traffic?.likes||0)+' · گیفت: '+(m.traffic?.gifts||0);box.append(traffic);$('connectLive').disabled=c.status==='connecting';$('connectLive').textContent=c.status==='connecting'?'در حال اتصال…':'اتصال با یوزرنیم'}
const likerRail=document.createElement('aside');likerRail.id='likerRail';likerRail.className='liker-rail';likerRail.setAttribute('aria-label','Live likes');document.querySelector('main').append(likerRail);const leftEdge=document.createElement('div'),rightEdge=document.createElement('div');leftEdge.className='reaction-edge edge-left';rightEdge.className='reaction-edge edge-right';leftEdge.setAttribute('aria-hidden','true');rightEdge.setAttribute('aria-hidden','true');document.querySelector('main').append(leftEdge,rightEdge);
function renderLikers(people){const rail=$('likerRail');if(!rail)return;rail.replaceChildren();const title=document.createElement('span');title.className='liker-title';title.textContent='LIVE LOVE';rail.append(title);people.slice(0,6).forEach((p,i)=>{const card=document.createElement('div');card.className='liker-card '+(p.tier||'basic');const face=document.createElement('div');face.className='liker-face';makeAvatar(face,p);if(p.tier==='crown'){const crown=document.createElement('b');crown.textContent='♛';crown.className='liker-crown';face.append(crown)}const label=document.createElement('strong');label.textContent=p.name;const count=document.createElement('small');count.textContent='♥ '+new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(p.likes);card.append(face,label,count);rail.append(card)});rail.hidden=people.length===0}
let reactionSide=0;function edgeHearts(count=1){for(let i=0;i<Math.min(6,Math.max(2,Math.ceil(Math.log10(count+1)*2)));i++){const el=document.createElement('span');el.className='edge-heart';el.textContent=i%3===0?'♡':'♥';el.style.left=(15+Math.random()*40)+'%';el.style.fontSize=(22+Math.random()*24)+'px';el.style.animationDelay=i*.12+'s';(reactionSide++%2?leftEdge:rightEdge).append(el);setTimeout(()=>el.remove(),3300)}}

const outputLinks=document.createElement('div');outputLinks.className='stream-link-help';outputLinks.innerHTML='<strong>لینک مخصوص نمایش در لایو</strong><p>این لینک را در منبع Browser / Website بگذارید؛ لینک مدیریت برای نمایش روی لایو نیست.</p><div class="map-row"><input id="liveScreenURL" readonly aria-label="Live screen URL"><button id="copyLiveScreen">کپی لینک نمایش</button></div><p>Width: 1080 · Height: 1920 · Fit / Contain · Crop: 0</p>';$('adminTools').prepend(outputLinks);$('liveScreenURL').value=location.origin+'/screen';$('copyLiveScreen').onclick=async()=>{try{await navigator.clipboard.writeText($('liveScreenURL').value);message('Live screen link copied.')}catch{$('liveScreenURL').select();message('Select and copy the live screen link.')}};if(streamOutput){document.documentElement.classList.add('stream-output');document.body.classList.add('broadcast');requestAnimationFrame(fitMobileLive)}

const playModeBox=document.createElement('section');playModeBox.className='visible-play-mode';playModeBox.innerHTML='<strong>تبدیل گیفت به عدد کامنت</strong><p>از همین‌جا روش بازی را انتخاب کنید:</p><div class="play-mode-buttons"><button id="playWithNumbers" type="button"><b>123</b><span>عدد کامنت</span><small>رایگان · 1، 2، 3، 4</small></button><button id="playWithGifts" type="button"><b>🌹</b><span>فقط گیفت</span><small>گیفت یک‌کوینی</small></button><button id="playWithBoth" type="button"><b>123 + 🌹</b><span>عدد و گیفت</span><small>هر دو فعال</small></button></div><p id="currentPlayMode" role="status"></p>';$('adminTools').prepend(playModeBox);const visibleModeButtons={comments:$('playWithNumbers'),gifts:$('playWithGifts'),both:$('playWithBoth')};for(const [value,button] of Object.entries(visibleModeButtons))button.onclick=()=>{command('set-input-mode',{inputMode:value});$('currentPlayMode').textContent='در حال ذخیرهٔ روش بازی…'};function updateVisiblePlayMode(){if(!$('currentPlayMode'))return;for(const [value,button] of Object.entries(visibleModeButtons)){button.classList.toggle('is-selected',value===inputMode);button.setAttribute('aria-pressed',String(value===inputMode))}$('currentPlayMode').textContent='روش فعلی: '+({comments:'عدد کامنت — رایگان',gifts:'فقط گیفت',both:'عدد کامنت و گیفت'}[inputMode]||inputMode)}updateVisiblePlayMode();if(!streamOutput&&new URLSearchParams(location.search).get('panel')==='1'){document.body.classList.remove('broadcast');window.scrollTo?.({top:0})}
